// FILE: frontend/src/TripMap.js (NEW FILE)
//
// --- VERSION 1.8.0 ---
// - This is a new, reusable component for displaying GPS data on a map.
// - It uses Leaflet.js and React-Leaflet.
// - It supports rendering a single trip path or multiple paths for comparison.
// -----------------------------

import React from 'react';
import { MapContainer, TileLayer, Polyline, Tooltip } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';

const CHART_COLORS = [ '#38BDF8', '#F59E0B', '#4ADE80', '#F472B6', '#A78BFA', '#2DD4BF', '#FB7185', '#FACC15', '#818CF8', '#FDE047' ];

function TripMap({ positions, multiRoute = false, labels = [] }) {
	const defaultPosition = [44.9778, -93.2650]; // Default to Minneapolis

	const getBounds = () => {
		const allPoints = multiRoute ? positions.flat() : positions;
		if (!allPoints || allPoints.length === 0) {
			return [[defaultPosition[0] - 0.1, defaultPosition[1] - 0.1], [defaultPosition[0] + 0.1, defaultPosition[1] + 0.1]];
		}
		const latitudes = allPoints.map(p => p[0]);
		const longitudes = allPoints.map(p => p[1]);
		return [
			[Math.min(...latitudes), Math.min(...longitudes)],
			[Math.max(...latitudes), Math.max(...longitudes)],
		];
	};

	const bounds = getBounds();

	return (
		<MapContainer bounds={bounds} style={{ height: '100%', width: '100%', backgroundColor: '#1F2937', borderRadius: '0.5rem' }}>
			<TileLayer
				attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>'
				url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
			/>
			{multiRoute ? (
				positions.map((path, index) => (
					<Polyline key={index} positions={path} color={CHART_COLORS[index % CHART_COLORS.length]}>
						<Tooltip>{labels[index] || `Trip ${index + 1}`}</Tooltip>
					</Polyline>
				))
			) : (
				<Polyline positions={positions} color={CHART_COLORS[0]} />
			)}
		</MapContainer>
	);
}

export default TripMap;
